<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\MagicLink\Infrastructure\Driven;

use PDO;
use Override;
use DateTimeImmutable;
use Civi\Lughauth\Features\Oidc\MagicLink\Domain\MagicLink;
use Civi\Lughauth\Features\Oidc\MagicLink\Domain\Gateway\MagicLinkGateway;

class MagicLinkSqlAdapter implements MagicLinkGateway
{
    public function __construct(
        private readonly PDO $pdo,
    ) {
    }

    #[Override]
    public function store(MagicLink $magicLink): void
    {
        $stmt = $this->pdo->prepare(
            'INSERT INTO _oauth_magic_link
                (uid, tenant_id, user_uid, client_id, token_hash, redirect_uri, scope, state, nonce, created_at, expires_at)
             VALUES
                (:uid, :tenant_id, :user_uid, :client_id, :token_hash, :redirect_uri, :scope, :state, :nonce, :created_at, :expires_at)'
        );
        $stmt->execute([
            'uid'          => $magicLink->uid,
            'tenant_id'    => $magicLink->tenantId,
            'user_uid'     => $magicLink->userUid,
            'client_id'    => $magicLink->clientId,
            'token_hash'   => $magicLink->tokenHash,
            'redirect_uri' => $magicLink->redirectUri,
            'scope'        => $magicLink->scope,
            'state'        => $magicLink->state,
            'nonce'        => $magicLink->nonce !== '' ? $magicLink->nonce : null,
            'created_at'   => $magicLink->createdAt->format('Y-m-d H:i:s'),
            'expires_at'   => $magicLink->expiresAt->format('Y-m-d H:i:s'),
        ]);
    }

    #[Override]
    public function findByHash(string $tokenHash, string $tenantId): ?MagicLink
    {
        $stmt = $this->pdo->prepare(
            'SELECT uid, tenant_id, user_uid, client_id, token_hash, redirect_uri, scope, state, nonce,
                    created_at, expires_at, used_at
             FROM _oauth_magic_link
             WHERE token_hash = :token_hash AND tenant_id = :tenant_id
             LIMIT 1'
        );
        $stmt->execute(['token_hash' => $tokenHash, 'tenant_id' => $tenantId]);
        $row = $stmt->fetch(PDO::FETCH_ASSOC);
        if (!is_array($row)) {
            return null;
        }
        return $this->hydrate($row);
    }

    #[Override]
    public function markUsed(string $uid): void
    {
        $stmt = $this->pdo->prepare(
            'UPDATE _oauth_magic_link SET used_at = :used_at WHERE uid = :uid'
        );
        $stmt->execute([
            'used_at' => (new DateTimeImmutable())->format('Y-m-d H:i:s'),
            'uid'     => $uid,
        ]);
    }

    /**
     * @param array<string, mixed> $row
     */
    private function hydrate(array $row): MagicLink
    {
        return new MagicLink(
            uid:         (string) $row['uid'],
            tenantId:    (string) $row['tenant_id'],
            userUid:     (string) $row['user_uid'],
            clientId:    (string) $row['client_id'],
            tokenHash:   (string) $row['token_hash'],
            redirectUri: (string) $row['redirect_uri'],
            scope:       (string) $row['scope'],
            state:       isset($row['state']) && $row['state'] !== '' ? (string) $row['state'] : null,
            nonce:       isset($row['nonce']) && $row['nonce'] !== null ? (string) $row['nonce'] : '',
            createdAt:   new DateTimeImmutable((string) $row['created_at']),
            expiresAt:   new DateTimeImmutable((string) $row['expires_at']),
            usedAt:      isset($row['used_at']) && $row['used_at'] !== null
                             ? new DateTimeImmutable((string) $row['used_at'])
                             : null,
        );
    }
}
